```javascript
import { gsap } from 'gsap';
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  PlaneGeometry,
  CylinderGeometry,
  RingGeometry,
  Mesh,
  Group,
  DoubleSide,
  RepeatWrapping,
  Vector2,
  Color,
  BackSide,
  AdditiveBlending,
  Matrix4,
  Euler,
  Quaternion,
  Object3D,
  TextureLoader,
} from 'three/webgpu';
import { float, uniform, mix, smoothstep, vec3, uv, time, positionWorld } from 'three/tsl';
import { createText } from '@/text';
import { orbit, depthRotate } from '@/primitives';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {};

  const { visualSpec } = config.intent || {};
  const colors = config.colors || visualSpec?.colors || {};
  const typography = config.typography || visualSpec?.typography || {};
  const textContent = config.textContent || visualSpec?.textContent || [];

  // --- Backdrop ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });
  // Build gradient via node material
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const uvs = uv();
  const gradient = float(uvs.y);
  const c0 = new Color(gradientStops[0].hex);
  const c1 = new Color(gradientStops[1].hex);
  const c2 = new Color(gradientStops[2].hex);
  const col = mix(
    mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(gradientStops[0].at, gradientStops[1].at, gradient)),
    vec3(c2.r, c2.g, c2.b),
    smoothstep(gradientStops[1].at, gradientStops[2].at, gradient)
  );
  backdropMat.colorNode = vec3(col);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Plinth ---
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 48);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 - 0.125; // top of plinth at y=-1.1, height 0.25, so center at -1.1-0.125
  group.add(plinth);

  // --- Contact shadow ---
  const shadowGeo = new RingGeometry(0, 1.6, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.55,
    side: DoubleSide,
  });
  // Radial gradient using distance from center
  const uvRing = uv();
  const center = vec2(0.5, 0.5);
  const dist = distance(uvRing, center);
  const opacity = smoothstep(0.0, 1.0, dist);
  shadowMat.opacityNode = float(1.0 - opacity) * 0.55;
  shadowMat.colorNode = vec3(0, 0, 0);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.y = -1.1 - 0.01; // just above plinth bottom
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // --- Load watch mesh ---
  const meshGroup = new Group();
  group.add(meshGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.traverse((child) => {
        if (child.isMesh) {
          // Apply watch material properties
          if (child.material) {
            child.material = new MeshPhysicalNodeMaterial({
              roughness: 0.52,
              metalness: 0.55,
              clearcoat: 0.2,
              clearcoatRoughness: 0.4,
              anisotropy: 0.8,
              anisotropyRotation: 0, // tangent, assume default
              color: new Color('#e8ecf2'), // paper tone
            });
            // copy map if any
            if (child.material.map) {
              // keep original texture
            }
          }
        }
      });
      // Normalize height to 2.2 scene units
      const box = new Box3().setFromObject(scene);
      const size = box.getSize(new Vector3());
      const scaleFactor = 2.2 / size.y;
      scene.scale.set(scaleFactor, scaleFactor, scaleFactor);
      // Center at origin
      const center = box.getCenter(new Vector3());
      scene.position.sub(center.clone().multiplyScalar(scaleFactor));
      scene.position.y = -1.1; // top of plinth
      meshGroup.add(scene);
    });
  }

  // --- Text ---
  const headlineText = textContent.find((t) => t.role === 'headline') || { text: 'Calibre NA-01', fontSize: 68, fontWeight: 600, letterSpacing: -0.005 };
  const bodyText = textContent.find((t) => t.role === 'body') || { text: 'Machined in-house. 41 mm. Grade 5 titanium.', fontSize: 26, letterSpacing: 0 };
  const captionText = textContent.find((t) => t.role === 'caption') || { text: 'FROM 4200 USD / SHIPS IN 21 DAYS', fontSize: 18, letterSpacing: 0.08 };

  // Headline
  const headline = ctx.fontAtlas.createText(headlineText.text, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: headlineText.letterSpacing * 68,
  });
  headline.position.set(0, -1.5, 0); // 1.5 units below scene center (center at y=0)
  group.add(headline);

  // Body
  const body = ctx.fontAtlas.createText(bodyText.text, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0,
  });
  body.position.set(0, -1.5 - 0.5, 0); // 0.5 units below headline
  group.add(body);

  // Caption
  const caption = ctx.fontAtlas.createText(captionText.text, {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: captionText.letterSpacing * 18,
  });
  caption.position.set(0, -1.5 - 0.5 - 0.3, 0); // additional spacing
  group.add(caption);

  // --- Lights ---
  // Key light (white, 1.2 intensity, 30-45 deg)
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  // Rim light (accent, intensity 1.5, left side)
  const rimLight = new ctx.THREE.DirectionalLight(0xff2a38, 1.5);
  rimLight.position.set(-2, 1, 3);
  group.add(rimLight);

  // Ambient fill
  const ambient = new ctx.THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambient);

  // --- Primitives ---
  const primitivesToApply = config.cinematicPrimitives || [];
  const cleanupFns = [];

  for (const p of primitivesToApply) {
    let result;
    if (p.name === 'orbit') {
      result = orbit(meshGroup, p.params);
    } else if (p.name === 'depth-rotate') {
      result = depthRotate(meshGroup, p.params);
    }
    if (result) {
      if (result.cleanup) cleanupFns.push(result.cleanup);
      if (result.timeline) {
        // store timeline for cleanup
        group.userData.cleanupTimelines = group.userData.cleanupTimelines || [];
        group.userData.cleanupTimelines.push(result.timeline);
      }
    }
  }

  // --- Event handlers ---
  group.userData.handlers = {
    pointermove: (event) => {
      // For depth-rotate, we need to pass cursor position relative to group
      // The primitive handles internally via magentic-cursor or similar, but we can provide a custom event
      // Since depth-rotate is applied, it will read from group's userData.cursorPosition if set
      const rect = group.userData.boundingRect; // assume set by parent
      if (rect) {
        const x = (event.clientX - rect.left) / rect.width - 0.5;
        const y = (event.clientY - rect.top) / rect.height - 0.5;
        group.userData.cursorPosition = { x, y };
      }
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    cleanupFns.forEach((fn) => fn());
    if (group.userData.cleanupTimelines) {
      group.userData.cleanupTimelines.forEach((tl) => tl.kill());
    }
    // Dispose geometries and materials
    backdrop.geometry.dispose();
    backdrop.material.dispose();
    plinth.geometry.dispose();
    plinth.material.dispose();
    shadow.geometry.dispose();
    shadow.material.dispose();
    // mesh materials are disposed by GLB loader cleanup if we keep reference, but we can traverse
    if (meshGroup.children.length) {
      meshGroup.traverse((child) => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (child.material) child.material.dispose();
        }
      });
    }
    // Text objects are Meshes with MSDF materials; dispose via ctx.fontAtlas?
    // We can dispose if we have reference. For simplicity, we assume fontAtlas handles cleanup.
    // But we must remove from parent
    if (headline.parent) headline.parent.remove(headline);
    if (body.parent) body.parent.remove(body);
    if (caption.parent) caption.parent.remove(caption);
  };

  return group;
}
